#include <stdio.h>

typedef long long ll;

int main(void) {
    ll x[8], y[8];
    int i;

    for (i = 1; i <= 7; i++) {
        if (scanf("%lld %lld", &x[i], &y[i]) != 2) return 0;
    }

    /* vetores auxiliares */
    ll v21x = x[2] - x[1], v21y = y[2] - y[1];
    ll v31x = x[3] - x[1], v31y = y[3] - y[1];
    ll v32x = x[3] - x[2], v32y = y[3] - y[2];
    ll v54x = x[5] - x[4], v54y = y[5] - y[4];
    ll v64x = x[6] - x[4], v64y = y[6] - y[4];
    ll v75x = x[7] - x[5], v75y = y[7] - y[5];

    int ok = 1;

    /* 1) angulo P2P1P3 agudo: produto escalar > 0 */
    if (v21x * v31x + v21y * v31y <= 0) ok = 0;

    /* 2) |P1P2| == |P1P3| */
    if (v21x * v21x + v21y * v21y != v31x * v31x + v31y * v31y) ok = 0;

    /* 3) P2, P3, P4, P5 colineares */
    if (v32x * (y[4] - y[2]) - v32y * (x[4] - x[2]) != 0) ok = 0;
    if (v32x * (y[5] - y[2]) - v32y * (x[5] - x[2]) != 0) ok = 0;

    /* 4) pontos medios de P2P3 e P4P5 coincidem: P2+P3 == P4+P5 */
    if (x[2] + x[3] != x[4] + x[5] || y[2] + y[3] != y[4] + y[5]) ok = 0;

    /* 5) |P2P3| > |P4P5| */
    if (v32x * v32x + v32y * v32y <= v54x * v54x + v54y * v54y) ok = 0;

    /* 6) P4P6 e P5P7 perpendiculares a P2P3 */
    if (v64x * v32x + v64y * v32y != 0) ok = 0;
    if (v75x * v32x + v75y * v32y != 0) ok = 0;

    /* 7) |P4P6| == |P5P7| */
    if (v64x * v64x + v64y * v64y != v75x * v75x + v75y * v75y) ok = 0;

    /* 8) P1 e P6 em lados opostos da reta que contem P2P3
          (segmento P1P6 intercepta a reta em exatamente um ponto) */
    {
        ll c1 = v32x * (y[1] - y[2]) - v32y * (x[1] - x[2]);
        ll c6 = v32x * (y[6] - y[2]) - v32y * (x[6] - x[2]);
        if (!((c1 > 0 && c6 < 0) || (c1 < 0 && c6 > 0))) ok = 0;
    }

    printf("%c\n", ok ? 'S' : 'N');
    return 0;
}
